parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "classifications": {
      "type": "array",
      "description": "Una clasificación por cada publicación recibida",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Identificador original de la publicación"
          },
          "sentiment": {
            "type": "string",
            "enum": ["POS", "NEG", "NEU"],
            "description": "Sentimiento de la publicación"
          }
        },
        "required": ["id", "sentiment"],
        "additionalProperties": false
      }
    }
  },
  "required": ["classifications"],
  "additionalProperties": false
}

parameters.jsCode:
const mergeItems = $input.all();

const topic = mergeItems.find(({ json }) =>
  json.topic_id !== undefined,
)?.json;

const classifications = mergeItems.find(({ json }) =>
  Array.isArray(json.output?.classifications),
)?.json.output.classifications;

const originalItems = Object.values(
  $('Scrapper').first().json.items ?? {},
);

if (!topic) {
  throw new Error('No se encontró el tópico');
}

if (!classifications) {
  throw new Error('No se encontraron las clasificaciones');
}

const originalById = new Map(
  originalItems.map((item) => [String(item.id), item]),
);

const classifiedAt = new Date().toISOString();
const seenIds = new Set();

const classifiedItems = classifications.map(({ id, sentiment }) => {
  const identifier = String(id);
  const original = originalById.get(identifier);

  if (!original) {
    throw new Error(`No se encontró el tweet con ID ${identifier}`);
  }

  if (seenIds.has(identifier)) {
    throw new Error(`ID duplicado: ${identifier}`);
  }

  if (!['POS', 'NEG', 'NEU'].includes(sentiment)) {
    throw new Error(`Sentimiento inválido: ${sentiment}`);
  }

  seenIds.add(identifier);

  const { id: _, ...tweet } = original;

  return {
    ...tweet,
    identifier,
    sentiment_llm: sentiment,
    llm_model: $env.MODEL,
    llm_prompt_version: '2',
    llm_classified_at: classifiedAt,
  };
});

return [
  {
    json: {
      id: topic.id,
      empty_streak: topic.empty_streak,
      topic_id: topic.topic_id,
      name: topic.name,
      page: topic.page,
      items: classifiedItems,
    },
  },
];
